import csv
TS='43017c43-0ad2-5eef-8e41-95a8780d3143'
def day_total(date):
    tot=0.0; n=0
    with open(VALUES_CSV) as f:
        r=csv.DictReader(f)
        for row in r:
            if row['timeseries_id']==TS and row['timestamp'].startswith(date):
                try:
                    tot+=float(row['value']); n+=1
                except: pass
    return tot,n
for d in ('2018-10-21','2018-01-26'):
    t,n=day_total(d)
    print(d, t, n)
